function remember(settings,id){if(!settings||typeof settings!=='object')return;if(!tool(id)||['tutorial','privacy','view'].includes(id))return;settings.recentTools=[id,...recent(settings).filter(x=>x!==id)].slice(0,4);}
function references(n){const out=new Set();if(typeof n.parentId==='string')out.add(n.parentId);const walk=(v,depth)=>{if(!v||typeof v!=='object'||depth>5)return;for(const [key,val]of Object.entries(v)){if(['sourceItemId','noteId','taskId'].includes(key)&&typeof val==='string')out.add(val);else if(val&&typeof val==='object')walk(val,depth+1);}};for(const k of ['journal','calendar','mindmap','reference','calculator'])walk(n[k],0);out.delete(n.id);return out;}
function connected(items,source){const ownRefs=references(source),own=new Set(source.relatedIds||[]);return items.filter(n=>n.id!==source.id&&!n.deletedAt).flatMap(n=>{const manual=own.has(n.id)||(n.relatedIds||[]).includes(source.id);return manual||ownRefs.has(n.id)||references(n).has(source.id)?[{item:n,manual}]:[];}).sort((a,b)=>String(b.item.updated).localeCompare(String(a.item.updated)));}
function link(source,target){if(!source||!target||source===target||source.id===target.id||source.deletedAt||target.deletedAt)throw Error('Choose another saved item.');const ids=source.relatedIds||[];if(ids.includes(target.id)||(target.relatedIds||[]).includes(source.id))return false;if(ids.length>=40)throw Error('This item already has 40 connections.');source.relatedIds=[...ids,target.id];return true;}
